      renderRows();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(form, error);
    } finally {
      button.disabled = archived;
    }
  });
  try {
    tasks = await api(endpoint);
    renderRows();
    button.disabled = archived;
  } catch (error) {
    showError(controls, error);
  }
}

